package pt.lawsjustice.domain;

import java.util.Map;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static pt.lawsjustice.domain.FinanceLedger.*;

class FinanceLedgerTest {
    private static UUID id(long n){return new UUID(0,n);}
    private static final UUID CHARGE=id(1),CASE=id(2),TARGET=id(3),PRESIDENT=id(4),PAYMENT=id(5),FRIEND=id(6),SENTENCE=id(7);
    private static FinanceLedger fined(){return FinanceLedger.empty().issueFine(CHARGE,CASE,TARGET,"Aveline",PRESIDENT,"President",CourtLedger.PRESIDENT,"Damage to the public lantern","CHRONICLES",500,1000);}
    private static FinanceLedger bail(){return FinanceLedger.empty().offerBail(CHARGE,SENTENCE,TARGET,"Aveline",PRESIDENT,"President",CourtLedger.PRESIDENT,"Authorized bail","EMERALD",5,1000);}
    private static FinanceLedger prepared(){return fined().prepare(PAYMENT,CHARGE,TARGET,"Aveline","RealAccount",2000);}
    private static FinanceLedger paid(){return prepared().settle(PAYMENT,3000);}

    @Test void finesFreezeTheAuthorizedCaseTargetAmountAndCurrency(){var ledger=fined();var c=ledger.charges().get(CHARGE);assertEquals(DUE,c.status());assertEquals(CASE.toString(),c.caseId());assertEquals("",c.sentence());assertEquals(500,c.amount());assertEquals("CHRONICLES",c.currency());assertEquals(PRESIDENT,c.author());assertEquals(CourtLedger.PRESIDENT,c.authority());assertTrue(ledger.payments().isEmpty());}
    @Test void oneCaseCannotReceiveTheSameFineTwiceEvenUsingAnotherIdentifier(){var ledger=fined();assertThrows(IllegalArgumentException.class,()->ledger.issueFine(CHARGE,CASE,TARGET,"Aveline",PRESIDENT,"President",CourtLedger.PRESIDENT,"Reason","CHRONICLES",1,2000));assertThrows(IllegalArgumentException.class,()->ledger.issueFine(id(99),CASE,TARGET,"Aveline",PRESIDENT,"President",CourtLedger.PRESIDENT,"Reason","CHRONICLES",1,2000));}
    @Test void negativeZeroOversizedAndUnknownCurrencyChargesAreRejected(){for(long amount:new long[]{Long.MIN_VALUE,-1,0,MAX_AMOUNT+1})assertThrows(IllegalArgumentException.class,()->FinanceLedger.empty().issueFine(CHARGE,CASE,TARGET,"Aveline",PRESIDENT,"President",CourtLedger.PRESIDENT,"Reason","CHRONICLES",amount,0));assertThrows(IllegalArgumentException.class,()->FinanceLedger.empty().issueFine(CHARGE,CASE,TARGET,"Aveline",PRESIDENT,"President",CourtLedger.PRESIDENT,"Reason","NEW_COIN",1,0));}
    @Test void arbitraryJobRolesNeverBecomeFinancialJudicialAuthority(){for(String role:new String[]{"GUARD","JUDGE","PRISON_CHIEF","","PRESIDENT_ELECT"})assertThrows(IllegalArgumentException.class,()->FinanceLedger.empty().offerBail(CHARGE,SENTENCE,TARGET,"Aveline",PRESIDENT,"Someone",role,"Reason","EMERALD",1,0));}
    @Test void preparationReservesOneAttemptWithoutCallingItAPayment(){var before=fined();var next=before.prepare(PAYMENT,CHARGE,TARGET,"Aveline","RealAccount",2000);assertTrue(before.payments().isEmpty());assertEquals(DUE,next.charges().get(CHARGE).status());assertEquals(PREPARED,next.pending(CHARGE).status());assertEquals(0,next.escrow("CHRONICLES"));assertEquals(1,next.preparedCount());assertEquals(500,next.pending(CHARGE).amount());}
    @Test void aFineCannotBeDebitedFromAnUnrelatedPlayer(){assertThrows(IllegalArgumentException.class,()->fined().prepare(PAYMENT,CHARGE,FRIEND,"Friend","OtherAccount",2000));}
    @Test void aFriendCanVoluntarilyPayAnAuthorizedBail(){var ledger=bail().prepare(PAYMENT,CHARGE,FRIEND,"Friend","OtherAccount",2000).settle(PAYMENT,3000);assertEquals(FRIEND.toString(),ledger.charges().get(CHARGE).closedBy());assertEquals(TARGET,ledger.charges().get(CHARGE).target());assertEquals(5,ledger.escrow("EMERALD"));}
    @Test void twoPreparedAttemptsCannotCompeteToChargeTheSameFine(){var ledger=prepared();assertThrows(IllegalArgumentException.class,()->ledger.prepare(id(99),CHARGE,TARGET,"Aveline","RealAccount",2100));assertThrows(IllegalArgumentException.class,()->ledger.prepare(PAYMENT,CHARGE,TARGET,"Aveline","RealAccount",2100));}
    @Test void settlingAReceiptMarksTheChargePaidAndFundsTheEscrowExactlyOnce(){var ledger=paid();assertEquals(PAID,ledger.charges().get(CHARGE).status());assertNull(ledger.pending(CHARGE));assertEquals(0,ledger.preparedCount());assertEquals(500,ledger.escrow("CHRONICLES"));assertEquals(0,ledger.escrow("EMERALD"));assertSame(ledger,ledger.settle(PAYMENT,9000));assertThrows(IllegalArgumentException.class,()->ledger.prepare(id(99),CHARGE,TARGET,"Aveline","RealAccount",4000));}
    @Test void unfundedAttemptsCannotBeForwardedToThePublicTreasury(){var ledger=prepared();assertThrows(IllegalArgumentException.class,()->ledger.transferred(PAYMENT,3000));assertEquals(0,ledger.escrow("CHRONICLES"));}
    @Test void markingAnIdempotentCrownTransferRemovesOnlyItsFundedEscrow(){var ledger=paid();var transferred=ledger.transferred(PAYMENT,4000);assertEquals(500,ledger.escrow("CHRONICLES"));assertEquals(0,transferred.escrow("CHRONICLES"));assertEquals(PAID,transferred.charges().get(CHARGE).status());assertEquals(CROWN,transferred.payments().get(PAYMENT).destination());assertSame(transferred,transferred.transferred(PAYMENT,5000));}
    @Test void aVerifiedUnfundedCancellationAllowsAFreshAttemptButCannotLaterSettle(){var cancelled=prepared().cancelPayment(PAYMENT,3000);assertEquals(DUE,cancelled.charges().get(CHARGE).status());assertNull(cancelled.pending(CHARGE));assertEquals(0,cancelled.escrow("CHRONICLES"));assertThrows(IllegalArgumentException.class,()->cancelled.settle(PAYMENT,4000));var next=cancelled.prepare(id(99),CHARGE,TARGET,"Aveline","RealAccount",4000);assertEquals(id(99),next.pending(CHARGE).id());}
    @Test void aSettledPaymentCannotBeCancelledOrJudiciallyRevokedAsIfUnpaid(){var ledger=paid();assertThrows(IllegalArgumentException.class,()->ledger.cancelPayment(PAYMENT,4000));assertThrows(IllegalArgumentException.class,()->ledger.revoke(CHARGE,PRESIDENT,"President",CourtLedger.PRESIDENT,"Withdraw fine",4000));}
    @Test void revocationPreservesTheOriginalAuthorityAndRecordsTheNewDecision(){var ledger=fined().revoke(CHARGE,FRIEND,"Next President",CourtLedger.PRESIDENT,"The fine is withdrawn",2000);var c=ledger.charges().get(CHARGE);assertEquals(REVOKED,c.status());assertEquals(PRESIDENT,c.author());assertEquals(FRIEND.toString(),c.closedBy());assertEquals("The fine is withdrawn",c.closingReason());assertThrows(IllegalArgumentException.class,()->ledger.prepare(PAYMENT,CHARGE,TARGET,"Aveline","RealAccount",3000));}
    @Test void pendingWalletWorkCannotBeRevokedBeforeItsReceiptIsResolved(){var ledger=prepared();assertThrows(IllegalArgumentException.class,()->ledger.revoke(CHARGE,PRESIDENT,"President",CourtLedger.PRESIDENT,"Withdraw",3000));}
    @Test void theEndOfCustodyExpiresOnlyUnpaidBailForThatSentence(){var expired=bail().reconcile(JusticeLedger.empty(),3000);assertEquals(EXPIRED,expired.charges().get(CHARGE).status());assertEquals("",expired.charges().get(CHARGE).closedBy());assertEquals(DUE,fined().reconcile(JusticeLedger.empty(),3000).charges().get(CHARGE).status());}
    @Test void aPendingBailReceiptIsResolvedBeforeExpiryRatherThanErasingPotentiallyPaidFunds(){var prepared=bail().prepare(PAYMENT,CHARGE,FRIEND,"Friend","OtherAccount",2000);assertSame(prepared,prepared.reconcile(JusticeLedger.empty(),3000));var paid=prepared.settle(PAYMENT,3000);assertEquals(PAID,paid.reconcile(JusticeLedger.empty(),4000).charges().get(CHARGE).status());}
    @Test void theSameSentenceCannotHaveTwoCurrentBailPrices(){var ledger=bail();assertThrows(IllegalArgumentException.class,()->ledger.offerBail(id(99),SENTENCE,TARGET,"Aveline",PRESIDENT,"President",CourtLedger.PRESIDENT,"Other price","EMERALD",10,2000));var revoked=ledger.revoke(CHARGE,PRESIDENT,"President",CourtLedger.PRESIDENT,"New offer to follow",2000);assertEquals(2,revoked.offerBail(id(99),SENTENCE,TARGET,"Aveline",PRESIDENT,"President",CourtLedger.PRESIDENT,"New offer","EMERALD",2,3000).charges().size());}
    @Test void restoredMapsAreImmutableAndMustMatchTheirIds(){var ledger=paid();assertEquals(ledger.state(),FinanceLedger.restore(ledger.state()).state());assertThrows(UnsupportedOperationException.class,()->ledger.charges().clear());assertThrows(IllegalArgumentException.class,()->new State(Map.of(id(99),ledger.charges().get(CHARGE)),ledger.payments()));assertThrows(IllegalArgumentException.class,()->new State(ledger.charges(),Map.of(id(99),ledger.payments().get(PAYMENT))));}
    @Test void aPaidChargeCannotBeRestoredWithoutItsMatchingFundedPayment(){var ledger=paid();assertThrows(IllegalArgumentException.class,()->new State(ledger.charges(),Map.of()));assertThrows(IllegalArgumentException.class,()->new State(fined().charges(),ledger.payments()));}
    @Test void clockRollbackClampsSettlementDatesWithoutChangingTheAmount(){var ledger=prepared().settle(PAYMENT,0);assertEquals(2000,ledger.payments().get(PAYMENT).settledAt());assertEquals(2000,ledger.charges().get(CHARGE).closedAt());assertEquals(500,ledger.escrow("CHRONICLES"));assertThrows(IllegalArgumentException.class,()->prepared().settle(PAYMENT,-1));}
}
